import { marked } from "marked";
import { readFileSync, writeFileSync } from "fs";
import { execFileSync } from "child_process";

const CHROME =
  "/home/nicholas-wood/.cache/puppeteer/chrome-headless-shell/linux-131.0.6778.204/chrome-headless-shell-linux64/chrome-headless-shell";

// jobs: [srcMdPath, outPdfPath, title]
const jobs: [string, string, string][] = JSON.parse(process.argv[2]);

const css = `
  @page { margin: 18mm 16mm; }
  * { box-sizing: border-box; }
  body { font-family: -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
    font-size: 11pt; line-height: 1.5; color: #1a1a1a; max-width: 100%; }
  h1 { font-size: 20pt; border-bottom: 2px solid #333; padding-bottom: 6px; margin-top: 0; }
  h2 { font-size: 15pt; margin-top: 22px; border-bottom: 1px solid #ccc; padding-bottom: 3px; }
  h3 { font-size: 12.5pt; margin-top: 16px; }
  h4 { font-size: 11pt; margin-top: 12px; }
  p, li { font-size: 11pt; }
  code { font-family: "SF Mono", Menlo, Consolas, monospace; font-size: 9.5pt;
    background: #f2f2f2; padding: 1px 4px; border-radius: 3px; }
  pre { background: #f6f8fa; border: 1px solid #e1e4e8; border-radius: 6px;
    padding: 10px 12px; overflow-x: auto; white-space: pre-wrap; word-wrap: break-word; }
  pre code { background: none; padding: 0; font-size: 9pt; }
  blockquote { border-left: 4px solid #ccc; margin: 10px 0; padding: 2px 14px; color: #444; }
  table { border-collapse: collapse; width: 100%; margin: 12px 0; font-size: 10pt; }
  th, td { border: 1px solid #ccc; padding: 6px 9px; text-align: left; vertical-align: top; }
  th { background: #f2f2f2; }
  hr { border: none; border-top: 1px solid #ddd; margin: 18px 0; }
  a { color: #0b5cad; text-decoration: none; }
  strong { color: #000; }
`;

for (const [src, outPdf, title] of jobs) {
  const md = readFileSync(src, "utf8");
  const html = `<!doctype html><html><head><meta charset="utf-8"><title>${title}</title><style>${css}</style></head><body>${marked.parse(md)}</body></html>`;
  const htmlPath = outPdf.replace(/\.pdf$/, ".html");
  writeFileSync(htmlPath, html);
  execFileSync(CHROME, [
    "--headless", "--no-sandbox", "--disable-gpu", "--no-pdf-header-footer",
    `--print-to-pdf=${outPdf}`, htmlPath,
  ], { stdio: "ignore" });
  console.log("rendered", outPdf);
}
